/**
 * The Compress result screen (redesign stage 3): what it says was done is what was done.
 *
 * The mockup's sample sentence ("Images re-encoded at 120 dpi… the words are byte-identical to the file you chose")
 * described a file that did not exist. The page's sentence is generated by describeCompressed() from the result's own
 * counts, and this runs that function on results shaped like the ones the compressor returns, in every branch.
 *
 * It also reads the built page: the new size first and the old one after "from", no arrow; the carry-over links still
 * in a `.nextup` block (src/lib/handoff.ts wires exactly that); and in a Pro build the offer's host under the result.
 *
 *   npm run verify:result
 */
import * as esbuild from 'esbuild';
import { mkdirSync, rmSync, readFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { join, dirname } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const WORK = join(ROOT, 'node_modules', '.cache', 'verify-result');
rmSync(WORK, { recursive: true, force: true });
mkdirSync(WORK, { recursive: true });

let fails = 0;
const ok = (cond, msg) => { console.log(`${cond ? 'ok  ' : 'FAIL'}  ${msg}`); if (!cond) fails++; };

await esbuild.build({
  entryPoints: [join(ROOT, 'src/lib/compress.ts')],
  bundle: true, platform: 'node', format: 'esm', outfile: join(WORK, 'compress.mjs'), logLevel: 'silent',
});
const { describeCompressed: described } = await import(pathToFileURL(join(WORK, 'compress.mjs')).href);
ok(typeof described === 'function', 'src/lib/compress.ts exports describeCompressed');
// Missing, every sentence check below fails by name rather than the script stopping before the page checks run.
const describeCompressed = typeof described === 'function' ? described : () => '(no describeCompressed)';

const base = { imagesRecompressed: 0, imagesSkipped: 0, imagesUndecodable: 0, writtenQuality: 72, writtenDpi: null, downscaled: 0, metadataStripped: true };
const say = (over) => describeCompressed({ ...base, ...over });
const TAIL = 'Text, vectors and form fields copied byte-for-byte.';

let s = say({ imagesRecompressed: 1, downscaled: 1, writtenDpi: 150 });
ok(s === `1 image re-encoded at quality 72 and downscaled to about 150 dpi. ${TAIL} Author and timestamps removed.`, `one image, downscaled: "${s}"`);

s = say({ imagesRecompressed: 5, downscaled: 2, writtenDpi: 144, imagesSkipped: 3, imagesUndecodable: 1, metadataStripped: false });
ok(s === `5 images re-encoded at quality 72, 2 of them downscaled to about 144 dpi; 2 images left as they were, because re-encoding would not have made them smaller; 1 image this browser could not read, left as it was. ${TAIL} Metadata kept as it was.`,
  `some downscaled, some kept, one unreadable, metadata kept: "${s}"`);

s = say({ imagesRecompressed: 4, downscaled: 4, writtenDpi: null });
ok(s === `4 images re-encoded at quality 72 and downscaled. ${TAIL} Author and timestamps removed.`, `all downscaled, no dpi measured, so none is claimed: "${s}"`);

s = say({});
ok(s === `No images to change. ${TAIL} Author and timestamps removed.`, `no images: "${s}"`);
ok(!/byte-identical|120 dpi/.test(say({ imagesRecompressed: 2 })), 'nothing from the mockup\'s sample sentence');

// The built page, in a free build (production's) and a Pro build.
const clean = { PDFIQ_PRO: '', PDFIQ_SALE: '', PDFIQ_LOCAL: '', CF_PAGES: '', CF_PAGES_BRANCH: '' };
for (const [label, env] of [['free build', {}], ['Pro build', { PDFIQ_PRO: '1' }]]) {
  const b = spawnSync(process.execPath, ['tools/build.mjs'], { cwd: ROOT, encoding: 'utf8', env: { ...process.env, ...clean, ...env } });
  ok(b.status === 0, `${label}: builds`);
  const html = readFileSync(join(ROOT, 'dist/compress/index.html'), 'utf8').replace(/\s+/g, ' ');
  const result = /<section aria-label="Result" data-view="result"[\s\S]*?<\/section>/.exec(html)?.[0] ?? '';
  ok(/<span class="res__now" data-after>[^<]*<\/span> <span class="res__was">from <s data-before>/.test(result) && !result.includes('→'),
    `${label}: the new size first, then "from" the old one, no arrow`);
  ok(/data-res-how/.test(result) && /data-try-smaller hidden/.test(result), `${label}: the summary sentence and "try smaller" (hidden until a harder setting would change the file)`);
  ok(/<div class="nextup">[\s\S]*href="\/split\/"[\s\S]*href="\/ocr\/"[\s\S]*href="\/merge\/"/.test(result), `${label}: the carry-over links are still a .nextup block, which the handoff wires`);
  if (env.PDFIQ_PRO) {
    ok(/<div data-pro-target-offer><\/div>/.test(result) && /or <a href="\/password\/">protect it<\/a> &mdash; no saving in between\./.test(result),
      `${label}: the Pro offer's host sits under the result, and "or protect it" ends the sentence`);
  } else {
    ok(!result.includes('data-pro-target') && !result.includes('/password/') && /, or <a href="\/merge\/">merge it with another<\/a> &mdash; no saving in between\./.test(result),
      `${label}: no Pro host and no Protect link; "or merge it with another" ends the sentence`);
  }
}

console.log(fails ? `\n${fails} FAILED` : '\nthe result screen says what was done, from the result itself');
process.exitCode = fails ? 1 : 0;
